def solve(n, k, soldiers):
    l = [0] * 101
    for s in soldiers:
        l[s] += 1

    blocking = 0
    result = 0
    for i in range(k, -1, -1):
        num_soldier = l[i]
        if num_soldier == 0:
            blocking = max(0, blocking - 1)
        else:
            blocking += num_soldier - 1
            result = blocking + k - i

    return result

    def __init__(self):
        n, self.k = [int(x) for x in input().split()]
        self.soldiers = [int(x) for x in input().split()]

    def solve(self):
        k, soldiers = self.k, self.soldiers
        ranks = Counter(soldiers)
        while ranks[k] < len(soldiers):
            self.answer += 1
            for i in range(k - 1, 0, -1):
                ranks[i + 1] += 1 if ranks[i] > 0 else 0

    def printAnswer(self):
        print(self.answer)

